SBQQ__Code__c:
export function isFieldEditableForObject(fieldName, line, conn, objectName) {
    let discountfields = ['SBQQ__Discount__c','SBQQ__AdditionalDiscountAmount__c','SBQQ__AdditionalDiscount__c'];
    let consultingProducts = ['CSSalary','CSEEHand'];
    let qleUnlockedProducts = ['TalentConnectPEO','TalentConnectTraditional','ITSTelepunchBasic','ITSTelepunchAdvanced','ITSProfSvcs','ITSTraining'];
    let isolveHardlist = ['NXGG2+Support','NXGG2+BioSupport','NXGLESupport','G7ClockSupport'];
    let discountfield = ['SBQQ__Discount__c','SBQQ__AdditionalDiscountAmount__c','SBQQ__AdditionalDiscount__c'];
    let clonedfield  = ['SBQQ__Discount__c','SBQQ__AdditionalDiscountAmount__c','SBQQ__AdditionalDiscount__c','NSP_List_Minimum_Fee__c','NSP_Final_Minimum_Fee__c'];
    let renewalProductsForDescChange = ['IPMUserLicense','IPMUserLicenseWO','IOPRTCoreLicense','IOPRTPlanningModule','IOPRTSuccessionPlanning','IOPRTCoreLicenseWO','IOPRTPlanningModuleWO','IOPRTSuccessionPlanningWO','IPMHRSupportCenter','IOPRTUserLicense','IOPRTStandardUserLicense','IOPRTUserLicenseWO','IOPRTStandardUserLicenseWO','IOPRTSSOModule'];

    if (objectName === 'QuoteLine__c')
    {	
        if(fieldName === 'NSP_Threshold_Applicable__c' || fieldName === 'NSP_List_Minimum_Fee__c' || fieldName === 'NSP_Final_Minimum_Fee__c' || fieldName === 'SBQQ__SubscriptionType__c' || fieldName === 'NSP_Upper_Bound_Pricing_Tier__c' || fieldName === 'SBQQ__BillingFrequency__c')
        {
            return false;
        }
        if(line.NSP_Threshold_Applicable__c === false && fieldName === 'NSP_Threshold_Percentage__c')
        {
            return false;
        }

        if((line.NSP_Scholarship_Price__c === true || line.SBQQ__Quote__r.NSP_WX_Scholarship__c == true) && discountfields.includes(fieldName))
        {
            return false;
        }

        if(line.NSP_IsClonedLine__c === true  &&  (isolveHardlist.includes(line.SBQQ__ProductCode__c) || line.NSP_Product_Type__c == 'Time & Attendance Hardware' || line.NSP_Product_Type__c == 'Learning Hosting' || line.NSP_Product_Type__c == 'Learning Select' || line.NSP_Product_Type__c == 'Learning Direct') && fieldName === 'NSP_Quoted_Quantity__c')
        {
            return true;
        }
        if((line.NSP_IsClonedLine__c === true&& line.SBQQ__PricingMethod__c === 'Block' && (fieldName!='NSP_Original_Price__c' && fieldName!='NSP_Delta_Discount__c' && fieldName!='NSP_Delta_Total__c')) || line.NSP_Original_Line__c === true || fieldName === 'NSP_Previous_Quantity__c')
        {
            return false;
        }
        //hide additional disc and show delta disc
        if(line.SBQQ__PricingMethod__c == 'Block' && (line.SBQQ__Source__c!=null || line.SBQQ__UpgradedSubscription__c!=null) && fieldName==='NSP_Delta_Discount__c')
        {
            return true;
        }
        //hide delta disc
        if(((line.SBQQ__PricingMethod__c == 'Block' && (line.SBQQ__Source__c===null || line.SBQQ__UpgradedSubscription__c===null)) || line.SBQQ__PricingMethod__c==='List') && fieldName ==='NSP_Delta_Discount__c'){
            return false;
        }
        if( (line.SBQQ__ProductCode__c.includes('CSSalary') || line.SBQQ__ProductCode__c.includes('CSEEHand')) && fieldName === 'NSP_Hourly_Day_Rate__c')
        {
            return false;
        }
        if(!line.SBQQ__ProductCode__c.includes('IRSOOnDemandTier') && fieldName === 'NSP_Positions__c')
        {
            return false;
        }

        if(!qleUnlockedProducts.includes(line.SBQQ__ProductCode__c) && line.SBQQ__Quote__r.SBQQ__Type__c !='Supplemental' && fieldName === 'NSP_Quoted_Quantity__c' && (line.SBQQ__Quote__r.NSP_Product_Type__c != 'Time and Attendance Hardware' && line.SBQQ__Quote__r.SBQQ__Type__c != 'Renewal' ) )
        {
            return false;
        }

        if(!renewalProductsForDescChange.includes(line.SBQQ__ProductCode__c) && (fieldName === 'NSP_QLE_Action_Type__c' || fieldName === 'NSP_QLE_Prior_Quantity__c' ))
        {
            return false;
        }

        if( fieldName === 'SBQQ__Quantity__c' )
        {
            return false;
        }

        if(line.NSP_Secondary_ListPrice__c >0 && fieldName === 'SBQQ__ListPrice__c')
        {
            return false;
        }

        if(line.NSP_Lock_On_QLI__c && line.SBQQ__Quote__r.NSP_TransactionType__c != 'Termination')
        {
            return false; // lock all fields 
        }

        if(!line.NSP_Lock_On_QLI__c && line.SBQQ__Quote__r.NSP_TransactionType__c == 'Termination')
        {
            return false; // lock all fields 
        }

        if(line.NSP_Lock_Discount__c && discountfield.includes(fieldName))
        {
            return false; // lock discount  fields 
        }

        if((!line.NSP_List_Minimum_Fee__c || line.SBQQ__Quote__r.NSP_WX_Scholarship__c )&& fieldName === 'NSP_Minimum_Fee_Discount_Amt__c'){
            return false;
        }

        if((line.SBQQ__Quote__r.SBQQ__Type__c == 'Amendment' && line.SBQQ__Quote__r.NSP_TransactionType__c != 'Termination') && (fieldName === 'SBQQ__EndDate__c' || fieldName ==='SBQQ__PriorQuantity__c' || fieldName ==='NSP_Delta_Total__c') )
        {
            return false;
        }
        if(line.SBQQ__Quote__r.NSP_TransactionType__c == 'Termination' && fieldName === 'NSP_Term_Line__c'){
            return false;
        }
    }
    if(objectName === 'Quote__c' && fieldName === 'NSP_Terminate_All__c'){
        return false;
    }
    if (objectName === 'Quote__c' && fieldName === 'NSP_WX_Scholarship__c') 
    {

        if (line.NSP_IsScholarshipEligiblePartner__c===false) 
        {
        return false;
        }

        if(line.NSP_IsScholarshipEligibleBPA__c != true)
        {

            return false;
        }
		if(line.SBQQ__Type__c == 'Amendment' && line.NSP_TransactionType__c != 'Termination') {
			 return false;
		}
    }


}

export function isFieldVisibleForObject(fieldName, line, conn, objectName) 
{

    let  nonHiddenfields = ['SBQQ__ProductCode__c','SBQQ__ProductName__c','SBQQ__Description__c','NSP_Clone_Required__c','NSP_Term_Line__c'];
    let renewalProductsForDescChange = ['IPMUserLicense','IPMUserLicenseWO','IOPRTCoreLicense','IOPRTPlanningModule','IOPRTSuccessionPlanning','IOPRTCoreLicenseWO','IOPRTPlanningModuleWO','IOPRTSuccessionPlanningWO','IPMHRSupportCenter','IOPRTUserLicense','IOPRTStandardUserLicense','IOPRTUserLicenseWO','IOPRTStandardUserLicenseWO','IOPRTSSOModule'];

    if (objectName === 'QuoteLine__c')
    {
        if((fieldName =='NSP_Final_Minimum_Fee__c' || fieldName === 'NSP_List_Minimum_Fee__c' || fieldName === 'NSP_Minimum_Fee_Discount_Amt__c') && (line.SBQQ__ProductCode__c == 'IWXContractors' || line.SBQQ__ProductCode__c == 'IWAContractors' || line.SBQQ__ProductCode__c == 'ITSUserLicenseWO' ))
        {
            return true;
        }

        if((fieldName =='NSP_Final_Minimum_Fee__c' || fieldName === 'NSP_List_Minimum_Fee__c' || fieldName === 'NSP_Minimum_Fee_Discount_Amt__c') && (line.SBQQ__ProductCode__c == 'HCMiSolvedHire' || line.SBQQ__ProductCode__c == 'HCMScheduling' || line.NSP_Parent_Product_Code__c == 'IWAPerCheckFee'))
        {
            return false;
        }

        if((fieldName =='NSP_Final_Minimum_Fee__c' || fieldName === 'NSP_List_Minimum_Fee__c' || fieldName === 'NSP_Minimum_Fee_Discount_Amt__c') 
            && line.SBQQ__Quote__r.NSP_Multiple_Companies__c && line.SBQQ__Quote__r.Total_Employess_of_all_companies__c && line.NSP_Multiple_CompaniesQuantityApplicable__c &&
            (!line.NSP_Max_Quantity__c ||   line.NSP_Max_Quantity__c < line.SBQQ__Quote__r.Total_Employess_of_all_companies__c) )
        {
            //return false;
        }

        if((fieldName =='NSP_Final_Minimum_Fee__c' || fieldName === 'NSP_List_Minimum_Fee__c' || fieldName === 'NSP_Minimum_Fee_Discount_Amt__c') && line.NSP_Include_In_IWA_bundle__c)
        {
            return false;
        }

        if( (fieldName =='NSP_Final_Minimum_Fee__c' || fieldName === 'NSP_List_Minimum_Fee__c' || fieldName === 'NSP_Minimum_Fee_Discount_Amt__c')&& (!line.NSP_Max_Quantity__c || line.NSP_Max_Quantity__c < line.NSP_Quoted_Quantity__c))
        {
            return false;
        }

        if(!renewalProductsForDescChange.includes(line.SBQQ__ProductCode__c) && (fieldName === 'NSP_QLE_Action_Type__c' || fieldName === 'NSP_QLE_Prior_Quantity__c' ))
        {
            return false;
        }

        if(line.NSP_Lock_On_QLI__c && !nonHiddenfields.includes(fieldName))
        {
            return false; // hide all fields 
        }
        if(fieldName == 'NSP_Terminate_All__c') {
            return false;
        }
    }
}

