export function updateQuantityonTermination(quote, lines) {
    debugger;
    let terminateAll =  quote.record["NSP_Terminate_All__c"];
    let quoteType =  quote.record["SBQQ__Type__c"];
    let quoteTransType = quote.record["NSP_TransactionType__c"];
    if(terminateAll == true && quoteType == 'Amendment' && quoteTransType == 'Termination')
            {
                lines.forEach(function(line) {
                let prodcode =line.record["SBQQ__ProductCode__c"];
                if(prodcode && prodcode!='IWAWaiver' && prodcode!='IWXWaiver'){
                line.record["NSP_Term_Line__c"] = true;
                line.record["SBQQ__Quantity__c"] = 0;
                line.record["NSP_Quoted_Quantity__c"] = 0;	 
                line.record["NSP_Terminate_All__c"] = true;
                }

            });
            }
}

export function undoQuantityUpdateonTerm(quoteModel, quoteLineModels) {
    debugger;
    let terminateAll =  quoteModel.record["NSP_Terminate_All__c"];
    let quoteType =  quoteModel.record["SBQQ__Type__c"];
    let quoteTransType = quoteModel.record["NSP_TransactionType__c"];

    if(quoteType == 'Amendment' && quoteTransType == 'Termination' && terminateAll == false)
            {
                quoteLineModels.forEach(function(line) {
                if(line.record["NSP_Previous_Quantity__c"] == null) {
                    line.record["NSP_Previous_Quantity__c"] = line.record["NSP_Quoted_Quantity__c"];
                }	
                if(line.record["NSP_Term_Line__c"] == true && line.record["NSP_Terminate_All__c"] == true) {
                if(line.record["NSP_Lock_On_QLI__c"] == true) {
                    line.record["SBQQ__Quantity__c"] = 	1;
                    line.record["NSP_Quoted_Quantity__c"] = 1;
                    line.record["NSP_Term_Line__c"] = false;
                    line.record["NSP_Terminate_All__c"] = false;
                }
                else if((line.record["NSP_Lock_On_QLI__c"] == false) && line.record["SBQQ__SubscriptionType__c"] == 'Evergreen') {
                    let upgradedSubs = 	line.RequiredBy__r;
            // let upgradedSubs = 	line.record[SBQQ__UpgradedSubscription__r.NSP_Quoted_Quantity__c];
                line.record["SBQQ__Quantity__c"] = 	1;
                line.record["NSP_Term_Line__c"] = false;
                line.record["NSP_Terminate_All__c"] = false;
                line.record["NSP_Quoted_Quantity__c"] = line.record["NSP_Previous_Quantity__c"];

                }
                else {
                line.record["SBQQ__Quantity__c"] = 	line.record["SBQQ__PriorQuantity__c"];
                line.record["NSP_Quoted_Quantity__c"] = line.record["SBQQ__PriorQuantity__c"];
                line.record["NSP_Term_Line__c"] = false;
                line.record["NSP_Terminate_All__c"] = false;
                }
                }
                else if(line.record["NSP_Term_Line__c"] == true && line.record["NSP_Terminate_All__c"] == false && line.record["NSP_Lock_On_QLI__c"] == true) {
                    line.record["SBQQ__Quantity__c"] = 	0;
                    line.record["NSP_Quoted_Quantity__c"] = 0;
                }
                else if(line.record["NSP_Term_Line__c"] == false && line.record["NSP_Terminate_All__c"] == false && line.record["NSP_Lock_On_QLI__c"] == true) {
                    line.record["SBQQ__Quantity__c"] = 	line.record["SBQQ__PriorQuantity__c"];
                    line.record["NSP_Quoted_Quantity__c"] = line.record["SBQQ__PriorQuantity__c"];;
                }


            });
            }
}

export function copyQuantityOnClonedlines(quote, lines){
    debugger;
    var productcountMap =  new Map();
    lines.forEach(function(line){
        let productId = 		line.record["SBQQ__Product__c"];
        let subscriptiontype = 	line.record["SBQQ__SubscriptionType__c"];
        if(productId && subscriptiontype)
        {
        productcountMap.set(productId+'_'+subscriptiontype,line);
        }
    });

    lines.forEach(function(line){
        let productId = 		line.record["SBQQ__Product__c"];
        let isclonedline = 	line.record["NSP_IsClonedLine__c"];

        if(productId && isclonedline && productcountMap.has(productId+'_'+'Renewable') )
        {
            line.record["SBQQ__Quantity__c"] = productcountMap.get(productId+'_'+'Renewable').record["SBQQ__Quantity__c"];
        }
    });
}

export function calculateWXSetupFee(quoteModel, quoteLines) {

            let iwxSetupFeeSum = 0;
            let iwxSetupFeeNetSum = 0;
            let multipleCompanies =  quoteModel.record["NSP_Multiple_Companies__c"];
            let totalEmployeeCompanies =  quoteModel.record["Total_Employess_of_all_companies__c"];
            let terminatingWoWs =  quoteModel.record["NSP_Terminating_WO_WS__c"];
            let wxScholarshipChecked =  quoteModel.record["NSP_WX_Scholarship__c"];
            //let overridefinalminimumfee = quoteModel.record["NSP_Override_Final_Minimum_Fee__c"];
            quoteModel.record["NSP_Show_Minimum_Text__c"]  = false;
            quoteModel.record["NSP_Show_Contractor_Minimum_Text__c"]  = false;
            let contractorlist = ['IWXContractors','IWAContractors'];

            quoteLines.forEach(function(line) {
            let setupFeeApplicableList = ['IWXBundleW2', 'IWXBundle','IWXContractors','HCMiSolvedHire','IWXPerCheckFee'];
            let setupProductList = ['IWXBundle','IWXBundleW2','IWACore','IWACoreW2','IWAPerCheckFee','IWXPerCheckFee'];
            let productCode = line.record["SBQQ__ProductCode__c"];
            let prodQuantity = line.record["NSP_Quoted_Quantity__c"];   
            let maxQuantity =  line.record["NSP_Max_Quantity__c"];
            let finalMinFee =  line.record["NSP_Final_Minimum_Fee__c"];
            let listMinFee = line.record["NSP_List_Minimum_Fee__c"];
            let listTotal =  line.record["NSP_List_Total_QQ__c"];
            let listunitTotal =  line.record["NSP_Net_List_Price__c"];
            let netTotal = line.record["NSP_Net_Total__c"];
            let listPrice =  line.record["SBQQ__ListPrice__c"];
            let scholarshipApplicable = line.record["NSP_Scholarship_Price__c"];
            let scholarshipMinFee = line.record["NSP_Scholarship_Min_Fee__c"];
            let isClonedLine = line.record["NSP_IsClonedLine__c"];
            let minimumfeediscount  = line.record["NSP_Minimum_Fee_Discount_Amt__c"];
            let lineWXSetupFee=0.0;
            let lineWXSetupNetFee = 0.0;
            let stopAutoPricing =  line.record["NSP_Stop_Auto_Pricing__c"];
            let multipleCompaniesapplicable = line.record["NSP_Multiple_CompaniesQuantityApplicable__c"];
            let isScholarshipApplied = line.record["NSP_IsScholarshipApplied__c"];
            let netUnitPrice =  line.record["SBQQ__NetPrice__c"];
            //let terminateLine =  line.record["Terminate__c"];


            if(!terminatingWoWs)
            {
                line.record["NSP_Stop_Auto_Pricing__c"] = false;
            }


            //if(!isClonedLine)
            {
                // copy list minimumfee to final minimumfee
                if(!scholarshipApplicable  && listMinFee > 0  ){
                    //minimumfeediscount  = minimumfeediscount > 0 ? minimumfeediscount: 0;
                    line.record["NSP_Final_Minimum_Fee__c"] = listMinFee - (minimumfeediscount);
                    finalMinFee = listMinFee - minimumfeediscount;
                }	

                if(scholarshipApplicable && finalMinFee && listMinFee){
                    //line.record["NSP_Final_Minimum_Fee__c"] = listMinFee;
                    line.record["NSP_Minimum_Fee_Discount_Amt__c"] = listMinFee - finalMinFee;
                    //finalMinFee = listMinFee;
                }

                if(setupProductList.includes(productCode) && finalMinFee != null && prodQuantity > 0){
                    quoteModel.record["NSP_WX_Minimum_Fee__c"] = prodQuantity <= maxQuantity ?finalMinFee : 0;
                    if(finalMinFee > 0 && (netUnitPrice * prodQuantity) < finalMinFee){
                        quoteModel.record["NSP_Show_Minimum_Text__c"]  = true;
                    }
                }
                //logic for contractor
                if(contractorlist.includes(productCode) && finalMinFee != null && prodQuantity > 0){
                    if(finalMinFee > 0 && (netUnitPrice * prodQuantity) < finalMinFee){
                        quoteModel.record["NSP_Show_Contractor_Minimum_Text__c"]  = true;
                    }
                }

                if(setupFeeApplicableList.includes(productCode) && !stopAutoPricing ) {

                    var selectquantity = prodQuantity;
                    if(multipleCompanies && totalEmployeeCompanies && multipleCompaniesapplicable)
                    {
                        //selectquantity = totalEmployeeCompanies; no longer needed DF-00691
                    }

                        if(selectquantity <= maxQuantity) {
                            if(productCode!='HCMiSolvedHire'){
                                lineWXSetupFee = Math.max(listPrice * prodQuantity, listMinFee);// listunitTotal;
                                lineWXSetupNetFee = netTotal;
                            }
                        }
                        else {
                            if(productCode!='HCMiSolvedHire'){
                                lineWXSetupFee = Math.max(listPrice * prodQuantity, listMinFee);//listunitTotal;
                                lineWXSetupNetFee = netTotal; 
                            }
                        }	
                    /* When multiple companies true
                    if(multipleCompanies && totalEmployeeCompanies  )
                    {
                        if(totalEmployeeCompanies <= maxQuantity) {
                            lineWXSetupFee = listMinFee;
                            lineWXSetupNetFee = finalMinFee;
                        }
                        else {
                            if(productCode!='HCMiSolvedHire'){
                                lineWXSetupFee = listTotal;
                                lineWXSetupNetFee = prodQuantity*listPrice;   
                            }
                        }
                    }*/ 


                }



                iwxSetupFeeSum+= lineWXSetupFee; 
                iwxSetupFeeNetSum+=lineWXSetupNetFee;
            }
            });
        quoteLines.forEach(function(line) {
            let productId = line.record["SBQQ__ProductCode__c"];
            let stopAutoPricing =  line.record["NSP_Stop_Auto_Pricing__c"];
                if(productId == 'IWXSU' && !stopAutoPricing){
                    line.record["SBQQ__ListPrice__c"] = iwxSetupFeeSum;
                }
                if(productId == 'IWXSU' && wxScholarshipChecked){
                    line.record["SBQQ__ListPrice__c"] = iwxSetupFeeSum;
                    line.record["SBQQ__AdditionalDiscountAmount__c"] = iwxSetupFeeSum-iwxSetupFeeNetSum;
                    line.record["SBQQ__Discount__c"] = null;
                    line.record["NSP_IsScholarshipApplied__c"] = true;
                }
            if(productId == 'IWXSU' && terminatingWoWs && !stopAutoPricing)
                {
                    line.record["SBQQ__ListPrice__c"] = 0;
                }
        });
}

