export function rollupListMinFee(quote,lines){
    let quoteType = quote.record["SBQQ__Type__c"];
	let quoteTransType = quote.record["NSP_TransactionType__c"];
    let rollUpValue=0;
    let productCodeList = ['IWXBundle','IWXBundleW2'];
    if(quoteType =='Amendment' && quoteTransType != 'Termination'){
        lines.forEach(function(line){
            if(line.record["SBQQ__UpgradedSubscription__c"]== null && line.record["NSP_Include_in_IWX_bundle_Rollup__c"]){
                rollUpValue+=line.record["NSP_Secondary_List_Minimum_Fee__c"];
            }
        });
        console.log('rollUpValue : '+rollUpValue);
        lines.forEach(function(line){
            if(line.record["SBQQ__UpgradedSubscription__c"] == null && productCodeList.includes(line.record["SBQQ__ProductCode__c"]) && rollUpValue>0 ){
                line.record["NSP_List_Minimum_Fee__c"] = rollUpValue;
            }
        });
    }
}

